package ru.artem.beforethefall.equipment;
import org.bukkit.Bukkit;import org.bukkit.ChatColor;import org.bukkit.Color;import org.bukkit.Material;import org.bukkit.NamespacedKey;import org.bukkit.entity.Player;import org.bukkit.event.EventHandler;import org.bukkit.event.Listener;import org.bukkit.event.block.Action;import org.bukkit.event.player.PlayerInteractEvent;import org.bukkit.inventory.EquipmentSlot;import org.bukkit.inventory.ItemStack;import org.bukkit.inventory.meta.ItemMeta;import org.bukkit.inventory.meta.LeatherArmorMeta;import org.bukkit.persistence.PersistentDataType;import org.bukkit.scheduler.BukkitTask;import ru.artem.beforethefall.BeforeTheFallPlugin;import java.util.List;
public final class GasMaskManager implements Listener {
 private final BeforeTheFallPlugin plugin;private final NamespacedKey marker,filter,filterItem;private BukkitTask task;
 public GasMaskManager(BeforeTheFallPlugin p){plugin=p;marker=new NamespacedKey(p,"gas_mask");filter=new NamespacedKey(p,"filter_ticks");filterItem=new NamespacedKey(p,"replacement_filter");}
 public ItemStack createMask(){ItemStack item=new ItemStack(Material.LEATHER_HELMET);LeatherArmorMeta meta=(LeatherArmorMeta)item.getItemMeta();meta.setColor(Color.fromRGB(42,52,47));meta.setDisplayName(ChatColor.DARK_GREEN+"Противогаз");meta.setCustomModelData(21);meta.setLore(List.of(ChatColor.GRAY+"Защита от радиоактивной пыли и пепла",ChatColor.GRAY+"Сменный фильтр: "+plugin.getConfig().getInt("gas-mask.filter-duration-seconds",900)+" секунд",ChatColor.YELLOW+"Надень в слот шлема"));meta.getPersistentDataContainer().set(marker,PersistentDataType.BYTE,(byte)1);meta.getPersistentDataContainer().set(filter,PersistentDataType.INTEGER,0);item.setItemMeta(meta);return item;}
 public ItemStack createFilter(){ItemStack item=new ItemStack(Material.PAPER);ItemMeta meta=item.getItemMeta();meta.setDisplayName(ChatColor.GREEN+"Сменный фильтр");meta.setCustomModelData(20);meta.setLore(List.of(ChatColor.GRAY+"Картридж для противогаза",ChatColor.GRAY+"Ресурс: "+plugin.getConfig().getInt("gas-mask.filter-duration-seconds",900)+" секунд"));meta.getPersistentDataContainer().set(filterItem,PersistentDataType.BYTE,(byte)1);item.setItemMeta(meta);return item;}
 public boolean isFilter(ItemStack item){if(item==null||!item.hasItemMeta())return false;Byte v=item.getItemMeta().getPersistentDataContainer().get(filterItem,PersistentDataType.BYTE);return v!=null&&v==(byte)1;}
 public boolean isMask(ItemStack item){if(item==null||!item.hasItemMeta())return false;Byte v=item.getItemMeta().getPersistentDataContainer().get(marker,PersistentDataType.BYTE);return v!=null&&v==(byte)1;}
 private int filterTicks(ItemStack item){if(!isMask(item))return 0;Integer v=item.getItemMeta().getPersistentDataContainer().get(filter,PersistentDataType.INTEGER);return v==null?0:v;}
 public int remainingSeconds(ItemStack item){return Math.max(0,filterTicks(item)/2);}
 private void setFilterTicks(ItemStack item,int ticks){ItemMeta meta=item.getItemMeta();int safe=Math.max(0,ticks);meta.getPersistentDataContainer().set(filter,PersistentDataType.INTEGER,safe);meta.setLore(List.of(ChatColor.GRAY+"Защита от радиоактивной пыли и пепла",ChatColor.GRAY+"Осталось: "+safe/2+" сек.",safe>0?ChatColor.GREEN+"Фильтр установлен":ChatColor.RED+"Фильтр пуст"));item.setItemMeta(meta);}
 public boolean isProtected(Player p){ItemStack h=p.getInventory().getHelmet();return isMask(h)&&filterTicks(h)>0;}
 @EventHandler public void onFilterUse(PlayerInteractEvent e){if(e.getHand()!=EquipmentSlot.HAND||(e.getAction()!=Action.RIGHT_CLICK_AIR&&e.getAction()!=Action.RIGHT_CLICK_BLOCK))return;ItemStack held=e.getItem();if(!isFilter(held))return;ItemStack helmet=e.getPlayer().getInventory().getHelmet();if(!isMask(helmet)){e.getPlayer().sendMessage(ChatColor.RED+"Сначала надень противогаз в слот шлема.");e.setCancelled(true);return;}int duration=Math.max(1,plugin.getConfig().getInt("gas-mask.filter-duration-seconds",900));setFilterTicks(helmet,duration*2);if(held.getAmount()>1)held.setAmount(held.getAmount()-1);else e.getPlayer().getInventory().setItemInMainHand(null);e.getPlayer().sendMessage(ChatColor.GREEN+"Фильтр установлен: "+duration/60+" минут защиты.");e.setCancelled(true);}
 public void start(){task=Bukkit.getScheduler().runTaskTimer(plugin,()->{for(Player p:Bukkit.getOnlinePlayers()){ItemStack h=p.getInventory().getHelmet();if(!isMask(h))continue;int r=filterTicks(h);if(r<=0)continue;setFilterTicks(h,r-1);if(r==1)p.sendMessage(ChatColor.RED+"Фильтр противогаза исчерпан!");}},10L,10L);}
 public void stop(){if(task!=null)task.cancel();}
}